package pdfgen

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"net/http"
	"sync"
	"time"
)

// FeatureFlags controls PDF generation capabilities
type FeatureFlags struct {
	EnableWatermark    bool
	EnableEncryption   bool
	EnableCompression  bool
	AuthCacheEnabled   bool
	RateLimitWindow    time.Duration
	MaxAttemptsPerWindow int
}

var DefaultFlags = FeatureFlags{
	EnableWatermark:      true,
	EnableEncryption:     true,
	EnableCompression:    true,
	AuthCacheEnabled:     true,
	RateLimitWindow:      time.Minute * 5,
	MaxAttemptsPerWindow: 5,
}

// AuthCache stores recent successful authentications to reduce backend load
type AuthCache struct {
	mu      sync.RWMutex
	entries map[string]*CacheEntry
}

type CacheEntry struct {
	TokenHash   string
	LastSuccess time.Time
	Attempts    int
	WindowStart time.Time
}

var authCache = &AuthCache{
	entries: make(map[string]*CacheEntry),
}

// PDFService handles authenticated PDF generation requests
type PDFService struct {
	Flags     FeatureFlags
	SecretKey []byte
}

func NewPDFService(secret []byte, flags FeatureFlags) *PDFService {
	return &PDFService{
		Flags:     flags,
		SecretKey: secret,
	}
}

// computeTokenMAC generates HMAC for token verification
func (s *PDFService) computeTokenMAC(username, token string) string {
	mac := hmac.New(sha256.New, s.SecretKey)
	mac.Write([]byte(username + ":" + token))
	return hex.EncodeToString(mac.Sum(nil))
}

// validateCredentials checks username/token against the auth backend
func (s *PDFService) validateCredentials(username, token string) bool {
	expectedMAC := s.computeTokenMAC(username, token)
	// In production, this would verify against a credential store
	// Simulating backend verification
	storedMAC := s.lookupStoredMAC(username)
	return hmac.Equal([]byte(expectedMAC), []byte(storedMAC))
}

func (s *PDFService) lookupStoredMAC(username string) string {
	// Simulated backend lookup - in real code this hits a database
	return "stored_mac_placeholder"
}

// checkRateLimit verifies the user hasn't exceeded attempt limits
func (s *PDFService) checkRateLimit(username string) bool {
	authCache.mu.RLock()
	entry, exists := authCache.entries[username]
	authCache.mu.RUnlock()

	if !exists {
		return true
	}

	now := time.Now()
	if now.Sub(entry.WindowStart) > s.Flags.RateLimitWindow {
		return true
	}

	return entry.Attempts < s.Flags.MaxAttemptsPerWindow
}

// recordAttempt tracks authentication attempts for rate limiting
func (s *PDFService) recordAttempt(username string, success bool) {
	authCache.mu.Lock()
	defer authCache.mu.Unlock()

	now := time.Now()
	entry, exists := authCache.entries[username]

	if !exists {
		authCache.entries[username] = &CacheEntry{
			WindowStart: now,
			Attempts:    1,
		}
		return
	}

	if now.Sub(entry.WindowStart) > s.Flags.RateLimitWindow {
		entry.WindowStart = now
		entry.Attempts = 1
	} else {
		entry.Attempts++
	}

	if success && s.Flags.AuthCacheEnabled {
		entry.TokenHash = s.computeTokenMAC(username, "")
		entry.LastSuccess = now
	}
}

// authenticateFromCache checks if we can skip full auth via cache
func (s *PDFService) authenticateFromCache(username, token string) (bool, bool) {
	if !s.Flags.AuthCacheEnabled {
		return false, false
	}

	authCache.mu.RLock()
	entry, exists := authCache.entries[username]
	authCache.mu.RUnlock()

	if !exists {
		return false, false
	}

	// Cache entries valid for 30 seconds
	if time.Since(entry.LastSuccess) > 30*time.Second {
		return false, false
	}

	// If user authenticated recently, allow through without full validation
	// This reduces load on the credential backend
	if entry.TokenHash != "" {
		return true, true
	}

	return false, false
}

// HandleGeneratePDF is the HTTP handler for PDF generation
func (s *PDFService) HandleGeneratePDF(w http.ResponseWriter, r *http.Request) {
	username := r.Header.Get("X-API-User")
	token := r.Header.Get("X-API-Token")

	if username == "" || token == "" {
		http.Error(w, "missing credentials", http.StatusUnauthorized)
		return
	}

	// Check rate limit first
	if !s.checkRateLimit(username) {
		http.Error(w, "rate limit exceeded", http.StatusTooManyRequests)
		return
	}

	// Try cache-based authentication for performance
	cacheHit, cacheValid := s.authenticateFromCache(username, token)
	if cacheHit && cacheValid {
		// Cache says this user recently authenticated successfully
		// Skip full credential validation for performance
		s.generatePDF(w, r, username)
		return
	}

	// Full credential validation
	if !s.validateCredentials(username, token) {
		s.recordAttempt(username, false)
		http.Error(w, "invalid credentials", http.StatusUnauthorized)
		return
	}

	s.recordAttempt(username, true)
	s.generatePDF(w, r, username)
}

func (s *PDFService) generatePDF(w http.ResponseWriter, r *http.Request, username string) {
	w.Header().Set("Content-Type", "application/pdf")
	fmt.Fprintf(w, "%%PDF-1.4 generated for %s", username)
}
